import React, { useState, useRef, useEffect } from 'react';
import axios from 'axios';
import { API_URL, testConnection } from '../utils/api';

const ImageProcessor = ({ colorblindType, mode }) => {
  const [originalImage, setOriginalImage] = useState(null);
  const [processedImage, setProcessedImage] = useState(null);
  const [accuracy, setAccuracy] = useState(null);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState(null);
  const fileInputRef = useRef(null);

  useEffect(() => { testConnection(); }, []);

  const processImage = async () => {
    const res = await fetch(originalImage);
    const blob = await res.blob();
    const formData = new FormData();
    formData.append("image", blob);
    formData.append("colorblind_type", colorblindType);
    formData.append("mode", mode);

    setLoading(true);
    const result = await axios.post(`${API_URL}/process-image`, formData);
    setProcessedImage(`data:image/png;base64,${result.data.processed_image}`);
    setAccuracy(result.data.accuracy);
    setLoading(false);
  };

  return (
    <div>
      <input type="file" ref={fileInputRef} accept="image/*"
        onChange={e => {
          const reader = new FileReader();
          reader.onload = ev => setOriginalImage(ev.target.result);
          reader.readAsDataURL(e.target.files[0]);
        }}
      />
      <button onClick={processImage} disabled={loading}>
        {loading ? "Processing..." : "Process Image"}
      </button>
      {processedImage && (
        <>
          <img src={processedImage} alt="Processed"/>
          <p>Filter Accuracy: {accuracy}%</p>
        </>
      )}
      {error && <p>{error}</p>}
    </div>
  );
};

export default ImageProcessor;
